function num(v) {
  if (v === null || v === undefined || v === "." || v === "") return null;
  const cleaned = String(v).replace("%", "").replace(",", ".").trim();
  const n = Number(cleaned);
  return Number.isFinite(n) ? n : null;
}

function getNode(name) {
  try {
    return $(name).first().json;
  } catch (error) {
    return null;
  }
}

function getNodeAll(name) {
  try {
    return $(name).all().map(item => item.json);
  } catch (error) {
    return [];
  }
}

function fredLatest(data) {
  const obs = data?.observations || [];
  const valid = obs.filter(o => num(o.value) !== null);
  const latest = num(valid[0]?.value);

  return {
    latest,
    d1: valid[1] && latest !== null ? latest - num(valid[1].value) : null,
    d5: valid[5] && latest !== null ? latest - num(valid[5].value) : null,
    d20: valid[20] && latest !== null ? latest - num(valid[20].value) : null,
    date: valid[0]?.date || null
  };
}

function fredPct(data) {
  const obs = data?.observations || [];
  const valid = obs.filter(o => num(o.value) !== null);
  const latest = num(valid[0]?.value);

  function pct(i) {
    const old = num(valid[i]?.value);
    if (latest === null || old === null || old === 0) return null;
    return ((latest - old) / old) * 100;
  }

  return {
    latest,
    d1: pct(1),
    d5: pct(5),
    d20: pct(20),
    date: valid[0]?.date || null
  };
}

function bundesbankCsvLatest(data) {
  const text = data?.data || "";
  const rows = String(text)
    .split("\n")
    .map(line => line.trim())
    .filter(line => /^\d{4}-\d{2}-\d{2};/.test(line))
    .map(line => {
      const parts = line.split(";");
      return { date: parts[0], value: num(parts[1]) };
    })
    .filter(row => row.value !== null)
    .reverse();

  const latest = rows[0]?.value ?? null;

  return {
    latest,
    d1: rows[1] && latest !== null ? latest - rows[1].value : null,
    d5: rows[5] && latest !== null ? latest - rows[5].value : null,
    d20: rows[20] && latest !== null ? latest - rows[20].value : null,
    date: rows[0]?.date || null
  };
}

function coinbasePrice(data) {
  return num(data?.data?.amount);
}

function alphaQuote(data) {
  const q = data?.["Global Quote"] || {};
  return {
    price: num(q["05. price"]),
    d1_pct: num(q["10. change percent"])
  };
}

function pctChange(current, old) {
  current = num(current);
  old = num(old);
  if (current === null || old === null || old === 0) return null;
  return ((current - old) / old) * 100;
}

function bps(v) {
  return v !== null && v !== undefined ? v * 100 : null;
}

function spread(a, b) {
  return a !== null && b !== null ? a - b : null;
}

function spreadD5(a, b) {
  if (a?.latest === null || b?.latest === null || a?.d5 === null || b?.d5 === null) return null;
  const spreadNow = a.latest - b.latest;
  const spread5dAgo = (a.latest - a.d5) - (b.latest - b.d5);
  return (spreadNow - spread5dAgo) * 100;
}

function eventSortDate(e) {
  return new Date(e.date || e.time || 0).getTime();
}

function eventPriority(name) {
  const priority = {
    "Non Farm Payrolls": 100,
    "Inflation Rate MoM": 95,
    "Core Inflation Rate MoM": 95,
    "ISM Services PMI": 90,
    "ISM Manufacturing PMI": 90,
    "Unemployment Rate": 85,
    "Average Hourly Earnings MoM": 80,
    "Initial Jobless Claims": 75,
    "JOLTs Job Openings": 70,
    "GDP Growth Rate QoQ Adv": 70
  };
  return priority[name] || 0;
}

function usdSignalFromEvent(eventName, actual, forecast) {
  if (actual === null || forecast === null) {
    return { surprise: "neutral", usd_signal: "NEUTRAL" };
  }

  let beat = actual > forecast;
  let miss = actual < forecast;

  if (["Unemployment Rate", "Initial Jobless Claims"].includes(eventName)) {
    beat = actual < forecast;
    miss = actual > forecast;
  }

  return {
    surprise: beat ? "positive" : miss ? "negative" : "neutral",
    usd_signal: beat ? "BULLISH" : miss ? "BEARISH" : "NEUTRAL"
  };
}

function latestUsEventFromEcoData(ecoData) {
  const surprises = Array.isArray(ecoData?.surprises) ? ecoData.surprises : [];
  const recentSummary = Array.isArray(ecoData?.recentSummary) ? ecoData.recentSummary : [];

  const candidates = [];

  for (const e of surprises) {
    if (!e || !e.event || e.actual === null || e.estimate === null || !e.date) continue;

    const actual = num(e.actual);
    const forecast = num(e.estimate);
    if (actual === null || forecast === null) continue;

    const signal =
      e.direction === "BEAT" ? { surprise: "positive", usd_signal: "BULLISH" } :
      e.direction === "MISS" ? { surprise: "negative", usd_signal: "BEARISH" } :
      usdSignalFromEvent(e.event, actual, forecast);

    candidates.push({
      event: e.event,
      key: e.key || null,
      actual,
      forecast,
      previous: e.prev ?? null,
      surprise_score: num(e.surprise),
      surprise: signal.surprise,
      usd_signal: signal.usd_signal,
      date: e.date,
      impact: e.impact || null,
      source: "surprises",
      priority: eventPriority(e.event),
      timestamp: eventSortDate(e)
    });
  }

  for (const e of recentSummary) {
    if (!e || !e.event || e.actual === null || e.estimate === null || !e.time) continue;

    const priority = eventPriority(e.event);
    if (!priority) continue;

    const actual = num(e.actual);
    const forecast = num(e.estimate);
    if (actual === null || forecast === null) continue;

    const signal = usdSignalFromEvent(e.event, actual, forecast);

    candidates.push({
      event: e.event,
      key: null,
      actual,
      forecast,
      previous: e.prev ?? null,
      surprise_score: forecast !== 0 ? Math.round(((actual - forecast) / Math.abs(forecast)) * 10000) / 100 : null,
      surprise: signal.surprise,
      usd_signal: signal.usd_signal,
      date: e.time,
      impact: e.impact || null,
      source: "recentSummary",
      priority,
      timestamp: eventSortDate(e)
    });
  }

  if (!candidates.length) return null;

  candidates.sort((a, b) => {
    const dateDiff = b.timestamp - a.timestamp;
    if (dateDiff !== 0) return dateDiff;
    return b.priority - a.priority;
  });

  const latestDate = candidates[0].timestamp;
  const sameDate = candidates.filter(c => c.timestamp === latestDate);
  sameDate.sort((a, b) => b.priority - a.priority);

  const selected = sameDate[0];

  return {
    event: selected.event,
    key: selected.key,
    actual: selected.actual,
    forecast: selected.forecast,
    previous: selected.previous,
    surprise_score: selected.surprise_score,
    surprise: selected.surprise,
    usd_signal: selected.usd_signal,
    date: selected.date,
    impact: selected.impact,
    source: selected.source
  };
}

function upcomingEventsFromEcoData(ecoData) {
  const calendar = ecoData?.calendar || [];
  if (!Array.isArray(calendar)) return [];
  return calendar.slice(0, 10);
}

const now = new Date();
const today = now.toISOString().slice(0, 10);

const previousRows = getNodeAll("Supabase | Get Previous Market Snapshots")
  .filter(r => r.snapshot_date && r.run_time_et)
  .filter(r => r.snapshot_date < today)
  .sort((a, b) => new Date(b.run_time_et) - new Date(a.run_time_et));

const uniquePreviousRows = [];
const seenDates = new Set();

for (const row of previousRows) {
  if (!seenDates.has(row.snapshot_date)) {
    uniquePreviousRows.push(row);
    seenDates.add(row.snapshot_date);
  }
}

function historyPct(current, field, index) {
  const oldRow = uniquePreviousRows[index];
  return oldRow ? pctChange(current, oldRow[field]) : null;
}

