  data_quality: {
    collector_status: missing.length ? "partial" : "complete",
    missing,
    history_rows_used: uniquePreviousRows.length,
    eco_events_found: ecoDataRaw?.data_quality?.usd_events_found || 0,
    upcoming_events_found: upcomingEvents.length,
    fed_bias_model_status: fedBiasRaw ? "connected" : "missing",
    notes: [
      "Layer 1 agents may read this row, but must not read other agent outputs.",
      "Germany 2Y is parsed from Bundesbank CSV.",
      "US-DE 2Y spread and 5-day spread delta are calculated when Germany 2Y and US 2Y are available.",
      "Gold d1/d5/d20, BTC d1/d5/d20 and NQ d5/d20 are calculated from previous Supabase market_snapshots.",
      "NQ d1_pct comes from Alpha Vantage change percent.",
      "latest_us_event is selected from Finnhub economic calendar using date first and event priority second.",
      "fed_bias is derived from recent US economic surprise balance via Code | Derive Fed Bias."
    ]
  },

  raw_payload: {
    previous_snapshot_dates_used: uniquePreviousRows.map(r => r.snapshot_date),
    eco_data: ecoDataRaw,
    fed_bias_model: fedBiasRaw,
    us2y,
    us10y,
    tips10y,
    de2y,
    de10y,
    uk10y,
    jp10y,
    vix,
    dxy,
    goldPrice,
    btcPrice,
    wti,
    brent,
    jpyUsd,
    gbpUsd,
    cadUsd,
    audUsd,
    eurusd,
    nq,
    proxy_spreads: {
      us_de_2y_spread: usDe2ySpread,
      us_de_2y_spread_d5_bps: usDe2ySpreadD5Bps,
      us_de_10y_spread: usDe10ySpread,
      us_jp_10y_spread: usJp10ySpread
    }
  }
};

return [{ json: row }];

const recent   = $('HTTP Request | Eco Calendar Recent - Finnhub').first().json.economicCalendar;
const upcoming = $('HTTP Request | Eco Calendar Upcoming - Finnhub').first().json.economicCalendar;

// Tier-1 US indicators with sigma values for surprise normalisation
const TIER1 = {
  'Non Farm Payrolls':          { key: 'NFP',           sigma: 80 },
  'Average Hourly Earnings MoM':{ key: 'AHE_MOM',       sigma: 0.1 },
  'Unemployment Rate':          { key: 'UNEMPLOYMENT',  sigma: 0.15 },
  'Core Inflation Rate MoM':    { key: 'CORE_CPI_MOM',  sigma: 0.1 },
  'Inflation Rate MoM':         { key: 'CPI_MOM',       sigma: 0.15 },
  'ISM Manufacturing PMI':      { key: 'ISM_MFG',       sigma: 2.5 },
  'ISM Services PMI':           { key: 'ISM_SVCS',      sigma: 2.5 },
  'GDP Growth Rate QoQ Adv':    { key: 'GDP_ADV',       sigma: 0.5 },
  'ADP Employment Change':      { key: 'ADP',           sigma: 50 },
  'Initial Jobless Claims':     { key: 'JOBLESS_CLAIMS',sigma: 15 },
  'JOLTs Job Openings':         { key: 'JOLTS',         sigma: 0.3 }
};

// Filter recent US high/medium impact events with actuals
const recentUS = (recent || []).filter(e =>
  e.country === 'US' &&
  ['high','medium'].includes(e.impact) &&
  e.actual !== null
);

// Filter upcoming US high/medium impact events without actuals
const upcomingUS = (upcoming || []).filter(e =>
  e.country === 'US' &&
  ['high','medium'].includes(e.impact) &&
  e.actual === null
);

// Compute surprise scores for tier-1 recent prints
const surprises = [];
for (const event of recentUS) {
  const tier1 = TIER1[event.event];
  if (!tier1) continue;
  if (event.actual === null || event.estimate === null) continue;
  const surprise = (event.actual - event.estimate) / tier1.sigma;
  surprises.push({
    key:       tier1.key,
    event:     event.event,
    date:      event.time.split(' ')[0],
    actual:    event.actual,
    estimate:  event.estimate,
    surprise:  Math.round(surprise * 100) / 100,
    direction: surprise > 0 ? 'BEAT' : surprise < 0 ? 'MISS' : 'IN LINE'
  });
}

// Format upcoming calendar
const calendar = upcomingUS.map(e => ({
  event:    e.event,
  time:     e.time,
  estimate: e.estimate,
  impact:   e.impact
}));

// Format recent all US high/medium events (not just tier-1) for prompt context
const recentSummary = recentUS.slice(-20).map(e => ({
  event:    e.event,
  time:     e.time.split(' ')[0],
  actual:   e.actual,
  estimate: e.estimate,
  prev:     e.prev,
  impact:   e.impact
}));

return [{
  json: {
    surprises,
    calendar,
    recentSummary
  }
}];

const eco = $('Code | Process Eco Data').first().json;

const surprises = eco.surprises || [];

let score = 0;
const reasons = [];

for (const s of surprises) {
  if (s.direction === "BEAT") {
    score += 1;
    reasons.push(`${s.event} beat forecast`);
  }

  if (s.direction === "MISS") {
    score -= 1;
    reasons.push(`${s.event} missed forecast`);
  }
}

let fed_bias = "neutral";

if (score >= 2) fed_bias = "hawkish";
if (score <= -2) fed_bias = "dovish";

return [
  {
    json: {
      fed_bias,
      fed_bias_score: score,
      fed_bias_reasons: reasons.slice(0, 5)
    }
  }
];

function clean(v) {
  if (v === null || v === undefined) return null;
  const s = String(v).trim();
  return s ? s : null;
}

function impactRank(impact) {
  const s = String(impact || "").toLowerCase();
  if (s.includes("high")) return 3;
  if (s.includes("medium")) return 2;
  if (s.includes("low")) return 1;
  return 0;
}

function priority(name) {
  const n = String(name || "").toLowerCase();
  if (n.includes("non farm") || n.includes("payroll")) return 100;
  if (n.includes("core cpi")) return 98;
  if (n.includes("cpi")) return 95;
  if (n.includes("fomc") || n.includes("fed")) return 95;
  if (n.includes("pce")) return 92;
  if (n.includes("ism")) return 90;
  if (n.includes("unemployment")) return 85;
  if (n.includes("average hourly")) return 82;
  if (n.includes("claims")) return 80;
  if (n.includes("retail sales")) return 75;
  if (n.includes("gdp")) return 75;
  return 0;
}

function eventTimestamp(row) {
  const iso = clean(row.scheduled_at_utc) || clean(row.event_time_utc);
  if (iso) {
    const parsedIso = new Date(iso);
    if (Number.isFinite(parsedIso.getTime())) return parsedIso.getTime();
  }

  const date = clean(row.event_date);
  const time = clean(row.event_time_text);
  if (!date || !time) return 0;
  const parsed = new Date(date + " " + String(time).replace(/am/i, " AM").replace(/pm/i, " PM"));
  return Number.isFinite(parsed.getTime()) ? parsed.getTime() : 0;
}

function eventKey(row) {
  return [
    clean(row.event_date) || "",
    clean(row.event_time_text) || "",
    clean(row.currency) || "",
    clean(row.event_name) || ""
  ].join("|").toLowerCase();
}

function validateRow(row) {
  const reasons = [];
  if (!clean(row.event_name)) reasons.push("missing_event_name");
  if (!clean(row.currency) && !clean(row.region)) reasons.push("missing_currency_or_region");
  if (!clean(row.impact) || impactRank(row.impact) === 0) reasons.push("invalid_impact");
  if (!eventTimestamp(row)) reasons.push("invalid_timestamp");
  if (!clean(row.source)) reasons.push("missing_source");
  return {
    valid: reasons.length === 0,
    reasons
  };
}

const rawEvents = $input.all().map((item) => item.json);
const deduped = [];
const seen = new Set();
const rejected = [];

for (const row of rawEvents) {
  const key = eventKey(row);
  if (seen.has(key)) continue;
  seen.add(key);
  const validation = validateRow(row);
  if (!validation.valid) {
    rejected.push({
      key,
      reasons: validation.reasons
    });
    continue;
  }
  deduped.push(row);
}

const completed = deduped
  .filter((row) => clean(row.actual) !== null)
  .map((row) => ({
    event: row.event_name,
    forecast: row.forecast,
    previous: row.previous,
    actual: row.actual,
    surprise: row.surprise_direction,
    usd_signal: row.currency_signal,
    date: row.event_date,
    time: row.event_time_text,
    impact: row.impact,
    priority: priority(row.event_name),
    impact_rank: impactRank(row.impact),
    timestamp: eventTimestamp(row),
    source: row.source,
    raw: row
  }))
  .sort((left, right) => {
    const timeDiff = right.timestamp - left.timestamp;
    if (timeDiff !== 0) return timeDiff;
    const impactDiff = right.impact_rank - left.impact_rank;
    if (impactDiff !== 0) return impactDiff;
    return right.priority - left.priority;
  });

const upcoming = deduped
  .filter((row) => clean(row.actual) === null)
  .map((row) => ({
    event: row.event_name,
    forecast: row.forecast,
    previous: row.previous,
    date: row.event_date,
    time: row.event_time_text,
    impact: row.impact,
    priority: priority(row.event_name),
    impact_rank: impactRank(row.impact),
    timestamp: eventTimestamp(row),
    source: row.source
