function usdSignalFromEvent(eventName, actual, forecast) {
  if (actual === null || forecast === null) {
    return { surprise: "neutral", usd_signal: "NEUTRAL" };
  }

  let beat = actual > forecast;
  let miss = actual < forecast;

  if (["Unemployment Rate", "Initial Jobless Claims"].includes(eventName)) {
    beat = actual < forecast;
    miss = actual > forecast;
  }

  return {
    surprise: beat ? "positive" : miss ? "negative" : "neutral",
    usd_signal: beat ? "BULLISH" : miss ? "BEARISH" : "NEUTRAL"
  };
}

function latestUsEventFromEcoData(ecoData) {
  const surprises = Array.isArray(ecoData?.surprises) ? ecoData.surprises : [];
  const recentSummary = Array.isArray(ecoData?.recentSummary) ? ecoData.recentSummary : [];

  const candidates = [];

  for (const e of surprises) {
    if (!e || !e.event || e.actual === null || e.estimate === null || !e.date) continue;

    const actual = num(e.actual);
    const forecast = num(e.estimate);
    if (actual === null || forecast === null) continue;

    const signal =
      e.direction === "BEAT" ? { surprise: "positive", usd_signal: "BULLISH" } :
      e.direction === "MISS" ? { surprise: "negative", usd_signal: "BEARISH" } :
      usdSignalFromEvent(e.event, actual, forecast);

    candidates.push({
      event: e.event,
      key: e.key || null,
      actual,
      forecast,
      previous: e.prev ?? null,
      surprise_score: num(e.surprise),
      surprise: signal.surprise,
      usd_signal: signal.usd_signal,
      date: e.date,
      impact: e.impact || null,
      source: "surprises",
      priority: eventPriority(e.event),
      timestamp: eventSortDate(e)
    });
  }

  for (const e of recentSummary) {
    if (!e || !e.event || e.actual === null || e.estimate === null || !e.time) continue;

    const priority = eventPriority(e.event);
    if (!priority) continue;

    const actual = num(e.actual);
    const forecast = num(e.estimate);
    if (actual === null || forecast === null) continue;

    const signal = usdSignalFromEvent(e.event, actual, forecast);

    candidates.push({
      event: e.event,
      key: null,
      actual,
      forecast,
      previous: e.prev ?? null,
      surprise_score: forecast !== 0 ? Math.round(((actual - forecast) / Math.abs(forecast)) * 10000) / 100 : null,
      surprise: signal.surprise,
      usd_signal: signal.usd_signal,
      date: e.time,
      impact: e.impact || null,
      source: "recentSummary",
      priority,
      timestamp: eventSortDate(e)
    });
  }

  if (!candidates.length) return null;

  candidates.sort((a, b) => {
    const dateDiff = b.timestamp - a.timestamp;
    if (dateDiff !== 0) return dateDiff;
    return b.priority - a.priority;
  });

  const latestDate = candidates[0].timestamp;
  const sameDate = candidates.filter(c => c.timestamp === latestDate);
  sameDate.sort((a, b) => b.priority - a.priority);

  const selected = sameDate[0];

  return {
    event: selected.event,
    key: selected.key,
    actual: selected.actual,
    forecast: selected.forecast,
    previous: selected.previous,
    surprise_score: selected.surprise_score,
    surprise: selected.surprise,
    usd_signal: selected.usd_signal,
    date: selected.date,
    impact: selected.impact,
    source: selected.source
  };
}

